public class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; next = null; }
}

public boolean hasCycle(ListNode head) {
    Set<ListNode> seen = new HashSet<>();
    ListNode curr = head;
    while (curr != null) {
        if (!seen.add(curr)) {
            return true;
        }
        curr = curr.next;
    }
    return false;
}

code.python:
class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def hasCycle(self, head: ListNode) -> bool:
    seen = set()
    curr = head
    while curr:
        if curr in seen:
            return True
        seen.add(curr)
        curr = curr.next
    return False

